export function joistMarks(p){const set=new Set();for(const m of p.modules){const z0=Math.min(...m.poly.map(q=>q[1]));for(const j of m.joists)set.add(Math.round((j.z-z0)*16)/16);}return [...set].sort((a,b)=>a-b);}
