 const ends=r=>{const m=[r.miterStart,r.miterEnd].filter(Boolean);return !m.length?'square at both walls':m.length===1?`mitered${square?'':` at ${deg(m[0])}`} at the corner end, square where it meets the wall`:`mitered at both ends${square?'':` (${deg(r.miterStart)} and ${deg(r.miterEnd)})`}`;};
 const run=r=>`${r.label}, ${inches(r.outside)} along the outside: ${r.pieces.length===1?`one piece ${inches(r.pieces[0])}, ${ends(r)}`:`${r.pieces.length} pieces, ${r.pieces.map(inches).join(' + ')}, butted square where they meet and ${ends(r).replace('at both ends','at the outer ends')}`}.`;
