const cycloramaHelp={76:['Lauan sheets flat on supports · good face up','Track saw or circular saw and straightedge, tape measure, square and pencil'],63:['Corner panels · work from behind','Tape measure, square, miter saw and pencil'],64:['Behind the corner panels · one panel at a time','Drill, pilot bit, clamps, wood glue and narrow-crown stapler'],66:['Full sheet flat on supports','Track saw or table saw, tape measure, straightedge and square'],67:['Square flat · good face up','Small nail, non-stretch string or a stick trammel, pencil and tape measure'],68:['Square flat · good face up','Small nail, non-stretch string or a stick trammel, pencil and tape measure'],69:['Square flat on supports','Circular saw and straightedge, or table saw with a sled'],70:['Triangle flat on the bandsaw table','Bandsaw with a ¼″ or wider blade, roller stand or helper, sanding block or spindle sander'],43:['Existing walls upright · inspect front and rear','Tape measure, stud/framing locator, square, cardboard, flexible batten, jigsaw or router, drill and clamps'],44:['Corner ribs level · walls remain upright','Level, clamps, drill, pilot bit, countersink and wood glue; work from behind the walls for the screws'],45:['Skin bent vertically around the wall corner','Helper, clamps, drill, countersink and wood glue'],46:['Floor ribs upright · work from inside the set','Template, saw, level, drill, countersink and clamps'],47:['Compound junction · inspect from floor level','Paper templates, flexible batten, jigsaw, clamps, drill and grazing work light'],48:['Finished curves · inspect from several camera angles','Taping knives, flexible sanding block, dust extraction, work light, roller and brush']};
