 if(cycloramaHelp[helpStage])return {phase:'Seamless corner',phaseIndex:9,orientation:cycloramaHelp[helpStage][0],tools:cycloramaHelp[helpStage][1]};
 const phaseIndex=stage===0?0:stage<=9?1:stage<=12?2:stage<=16?3:stage<=20?4:stage<=22?5:stage>=30&&stage<40?8:stage<=26||stage===27&&floor!=='wood'?6:7;
 const orientation=platformHelp[stage]?platformHelp[stage][0]:stage===0?'Parts laid flat':stage<=9?'Flat on bench · frame side up':stage<=12?'Flat on supports · skin side up':stage<=16?'Jacks on their sides · inboard faces up':stage<=20?'Panel upright · work from behind':stage<=22?'Walls upright · secure supports':stage<=26?'Floor flat · look down into the set':stage===27?'Finish at floor level':'Walls upright · work from the front';
 const tools=platformHelp[stage]?platformHelp[stage][1]:stage===0?'Tape measure, square, pencil and saw':stage<=8?'Tape measure, square and clamps':stage===9?'Wood glue, clamps, drill, pilot bit and countersink':stage<=12?'Wood glue, clamps and narrow-crown stapler':stage<=16?'Square, clamps, saw, wood glue and drill':stage===17?'Helper, clamps, drill/driver, #2 Phillips bit, clearance bit, pilot bit and countersink':stage<=19?'Drill/driver, matching driver bit, pilot bit and countersink':stage===20?'Ballast':stage<=22?'Helper, clamps, drill and independent braces':stage===25&&floor==='charcoal'?'Flexible putty knives, 5″ random-orbit (DA) sander with 120 and 180 grit, low work light, shop vacuum, damp cloths, respirator and knee pads':stage===26&&floor==='charcoal'?'Roller, brush, tray and extension pole; DA sander with 220 grit, shop vacuum and damp cloths between coats':stage<=26?'Tape measure and tools specified by the floor manufacturer':'Sanding and finishing tools specified by the coating manufacturer';
