 function outlines(polys,y){const pts=[];for(const pg of polys)pg.forEach((a,i)=>{const b=pg[(i+1)%pg.length];pts.push(a[0]*inch,y,a[1]*inch,b[0]*inch,y,b[1]*inch);});return pts;}
